def transform(grid):
    # Continue the 9 and 4 diagonal sequences and preserve the separate 1 marks.
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = 3
    for color, dr, dc in ((9, 1, 1), (4, 1, -1)):
        pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        if len(pts) < 2:
            continue
        # These colors form respective continuous descending diagonals.
        if color == 9:
            r, c = 22, 2
        elif color == 4:
            r, c = 21, 4
        else:
            r, c = 24, 1
        while 0 <= r-dr < h and 0 <= c-dc < w:
            r -= dr; c -= dc
        while 0 <= r < h and 0 <= c < w:
            if out[r][c] == bg:
                out[r][c] = color
            r += dr; c += dc
    return out

